 wallpapers/image/plugin/imagebackend.cpp      | 46 +++++++++++++++++++
 wallpapers/image/plugin/imagebackend.h        |  2 +
 3 files changed, 52 insertions(+)

diff --git a/wallpapers/image/imagepackage/contents/ui/main.qml b/wallpapers/image/imagepackage/contents/ui/main.qml
index 14aac831f8..ffdf85e2e0 100644
--- a/wallpapers/image/imagepackage/contents/ui/main.qml
+++ b/wallpapers/image/imagepackage/contents/ui/main.qml
@@ -86,6 +86,10 @@ WallpaperItem {
             // Not using root.configuration.Image to avoid binding loop warnings
             configMap: root.configuration
             usedInConfig: false
+            onUsersWallpaperDownloaded: path => {
+                root.configuration.Image = path;
+                root.configuration.writeConfig();
+            }
             //the oneliner of difference between image and slideshow wallpapers
