 }

+void ImageBackend::downloadUsersWallpaper(const QUrl &url)
+{
+    auto job = KIO::storedGet(url, KIO::NoReload, KIO::HideProgressInfo);
+    connect(job, &KJob::result, this, [this, job, url] {
+        if (job->error()) {
+            return;
+        }
+
+        const QByteArray data = job->data();
+        const QMimeType mimeType = QMimeDatabase().mimeTypeForData(data);
+        if (!mimeType.name().startsWith(QLatin1String("image/"))) {
+            return;
+        }
+
+        QString fileName = url.fileName();
+        if (fileName.isEmpty()) {
+            fileName = QStringLiteral("wallpaper");
+        }
+        if (!isAcceptableSuffix(QFileInfo(fileName).suffix())) {
+            fileName += QLatin1Char('.') + mimeType.preferredSuffix();
+        }
+
+        const QString folder = QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + QStringLiteral("/wallpapers/");
+        if (QFileInfo::exists(folder + fileName)) {
+            fileName = KFileUtils::suggestName(QUrl::fromLocalFile(folder), fileName);
+        }
+
+        QFile file(folder + fileName);
+        if (!QDir().mkpath(folder) || !file.open(QIODevice::WriteOnly) || file.write(data) != data.size()) {
+            return;
+        }
+        file.close();
+
+        if (const QString result = addUsersWallpaper(QUrl::fromLocalFile(file.fileName())); !result.isEmpty()) {
+            Q_EMIT usersWallpaperDownloaded(result);
+        }
+    });
+}
